raw = state.get('filtered_entities') or []
if isinstance(raw, str):
    raw = []
chem = {}
dis = {}
for e in raw:
    if not isinstance(e, dict):
        continue
    lbl = e.get('label') or e.get('type') or ''
    eid = e.get('id') or e.get('mesh') or ''
    txt = e.get('text') or ''
    if not eid or not txt:
        continue
    if lbl == 'Chemical':
        chem[eid] = txt
    elif lbl == 'Disease':
        dis[eid] = txt
pairs = []
for hid, htxt in chem.items():
    for tid, ttxt in dis.items():
        pairs.append({'head': htxt, 'tail': ttxt, 'head_id': hid, 'tail_id': tid})
__result__ = pairs
